type Event struct { ID string; Type EventType `gorm:"column:event_type;not null"`; Source string; TaskID string; FromStatus string; ToStatus string; Details string; CreatedAt time.Time }
type EventDelivery struct { EventID string; Agent string; DeliveredAt time.Time; AckedAt *time.Time }
type Bus struct { db *gorm.DB }

patterns_to_follow.example:
func (b *Bus) UnackedDeliveries(agent string) ([]Event, error) {
	var events []Event
	err := b.db.Raw(`
		SELECT e.* FROM events e
		JOIN event_deliveries d ON d.event_id = e.id
		WHERE d.agent = ? AND d.acked_at IS NULL
		ORDER BY e.created_at ASC
	`, agent).Scan(&events).Error
	if err != nil {
		return nil, err
	}
	if events == nil {
		events = []Event{}
	}
	return events, nil
}
